theorem pentagonal_number_theorem (R : Type*) [CommRing R] :
  (PowerSeries.mk fun (n : ℕ) =>
    if h : ∃ k : ℤ, pentagonal k = n then
      if Even (Classical.choose h) then (1 : R) else (-1 : R)
    else 0) =
  ∑' k : ℤ, PowerSeries.monomial (pentagonal k) (if Even k then (1 : R) else (-1 : R)) := sorry
